        leaf = tool.Leaf('events', 'example', 'content/events/arc_midgame.json', ('description',), '고맙다. 그리고 미안했다. 둘 다.', 'event_standard')
        for suffix in ('人', '小时', '月', '公里', '股份'):
            self.assertTrue(tool.translation_errors(leaf, 'zh-CN', '两样' + suffix + '。'), suffix)

