    def test_career_specialization_exposed_grammar(self):
        cases = self._career_specialization_exposed_cases()
        self.assertEqual(len(cases), 24)
        for case in cases:
            _, owner, pointer = case["owner_id"].split(":")
            path = tuple(int(part) if part.isdigit() else part
                         for part in pointer[1:].split("/"))
            leaf = tool.Leaf("events", owner, "career-specialization-exposed", path,
                             case["source"], "event_standard")
            with self.subTest(identity=case["id"]):
                helper = tool._ja_career_specialization_numbers(case["source"], case["target"])
                errors = tool.translation_errors(leaf, "ja", case["target"])
                if case["expect"] == "helper_off":
                    # Exact source licence-OFF, not a generic semantic certificate.
                    self.assertIsNone(helper)
                elif case["expect"] == "pass":
                    self.assertEqual(errors, [])
                    self.assertIsNotNone(helper)
                    self.assertEqual(helper[2], [])
                else:
                    self.assertTrue(errors)
                    self.assertIsNotNone(helper)
                    self.assertTrue(helper[2])

