    def test_life_ledger_reflection_typed_quantities(self):
        cases = self._life_ledger_reflection_cases()
        self.assertEqual(len(cases), 294)
        self.assertEqual(tool.digest([case[:5] for case in cases]),
                         "e1453101e973bffd64a8890c0d6017db5561312368161fba1c863636a7405553")
        for case_id, _, expect, source, target, owner_id, source_path in cases:
            _, owner, pointer = owner_id.split(":")
            path = tuple(int(part) if part.isdigit() else part
                         for part in pointer[1:].split("/"))
            leaf = tool.Leaf("events", owner, source_path, path, source,
                             "event_standard")
            with self.subTest(identity=case_id):
                result = tool._ja_life_ledger_reflection_numbers(source, target)
                errors = tool.translation_errors(leaf, "ja", target)
                if expect == "helper_off":
                    # OFF only: do not turn this into generic semantic evidence.
                    self.assertIsNone(result)
                elif expect == "source_reject":
                    self.assertIsNone(result)
                    self.assertTrue(errors)
                elif expect == "pass":
                    self.assertIsNotNone(result)
                    self.assertEqual(result[2], [])
                    self.assertEqual(errors, [])
                else:
                    self.assertIsNotNone(result)
                    self.assertTrue(result[2])
                    self.assertTrue(errors)

