        for row in data["cases"]:
            item = {k: row[k] for k in ("id", "locale", "leaf_id", "expected")}
            for field in ("source", "target"):
                value = data[field + "s"][row[field + "_base"]]
                for start, old, new in reversed(row[field + "_edits"]):
                    self.assertEqual(value[start:start + len(old)], old)
                    value = value[:start] + new + value[start + len(old):]
                item[field] = value
            reconstructed.append(item)
        self.assertEqual(len(reconstructed), 155)
        self.assertEqual(tool.digest(reconstructed), '782361828805a55d4055e00e59b45cf48d1b088cd9a725d3500c2e7889437658')
        for row in reconstructed:
            with self.subTest(case=row["id"]):
                _, owner, pointer = row["leaf_id"].split(":", 2)
                path = tuple(int(x) if x.isdecimal() else x for x in pointer.strip("/").split("/"))
                leaf = tool.Leaf("events", owner, "content/events/arc_midgame.json", path, row["source"], "event_standard", "shipping")
                errors = tool.translation_errors(leaf, row["locale"], row["target"])
                if row["expected"] is None:
                    if row["locale"] == "ja":
                        self.assertIsNone(ja._midgame_win_numbers(row["source"], row["target"]))
                    else:
                        self.assertIsNone(z._midgame_kind(row["source"]))
                        self.assertEqual(z._midgame_slots(row["source"], row["target"]), ([], [], []))
                else:
                    self.assertEqual(not errors, row["expected"], errors)
                    if row["locale"] == "ja":
                        local = ja._midgame_win_numbers(row["source"], row["target"])
                        self.assertIsNotNone(local)
                        self.assertEqual(not local[2], row["expected"], local[2])


